                  !c.isRequired && h('span', {
                    style: { fontSize: '10px', padding: '1px 5px', borderRadius: '3px', background: 'rgba(125, 125, 125, 0.1)', color: 'var(--dsw-alias-text-sub, #71717a)' },
                  }, '选修')
